package com.caramel.chat.api;

import jakarta.validation.constraints.NotBlank;

/**
 * Body of POST /api/chat.
 *
 * <p>The 2,000-character limit is NOT a {@code @Size} constraint here. Over-length input must return
 * HTTP 413 per contracts/chat-api.md, while {@code @Size} would produce 400. The length check lives in
 * {@link com.caramel.chat.api.ChatController}.
 *
 * @param sessionId generated by the browser client; required on every request; non-blank
 * @param message   user text; non-blank
 */
public record ChatRequest(
        @NotBlank String sessionId,
        @NotBlank String message) {
}
